import { inject, NgModule } from '@angular/core';
import { MatIconRegistry } from '@angular/material/icon';
import { DomSanitizer } from '@angular/platform-browser';
import { SATORI_ICONS } from '@hylandsoftware/satori-icons';

/**
 * @deprecated Use provideSatoriIcons from @hylandsoftware/satori-ui/icons instead
 */
@NgModule()
export class SatIconModule {
  constructor() {
    const registry = inject(MatIconRegistry);
    const sanitizer = inject(DomSanitizer);
    registry.addSvgIconSetLiteral(sanitizer.bypassSecurityTrustHtml(SATORI_ICONS)); // NOSONAR Safe operation using trusted Satori artifact
    // support temporary _24px suffixed icons name
    // TODO: major release: remove support for _24px suffixed icons name
    registry.addSvgIconSetLiteral(
      sanitizer.bypassSecurityTrustHtml(SATORI_ICONS.replaceAll(/id="([^"]*)"/gi, 'id="$1_24px"')), // NOSONAR Safe operation using trusted Satori artifact
    );
  }
}
