import { DOCUMENT } from '@angular/common';
import {
  EnvironmentProviders,
  inject,
  makeEnvironmentProviders,
  provideAppInitializer,
} from '@angular/core';
import { MatIconRegistry } from '@angular/material/icon';
import { DomSanitizer } from '@angular/platform-browser';
import { SATORI_ICONS } from '@hylandsoftware/satori-icons';

export function provideSatoriIcons(): EnvironmentProviders {
  return makeEnvironmentProviders([
    provideAppInitializer(() => {
      const registry = inject(MatIconRegistry);
      const sanitizer = inject(DomSanitizer);
      const document = inject(DOCUMENT);

      registry.addSvgIconSetLiteral(sanitizer.bypassSecurityTrustHtml(SATORI_ICONS));

      const errorSvg = /<svg id="error"[^>]*>[\s\S]*?<\/svg>/.exec(SATORI_ICONS)?.[0] ?? null;
      if (errorSvg) {
        const standaloneSvg = errorSvg.includes('xmlns=')
          ? errorSvg
          : errorSvg.replace('<svg', '<svg xmlns="http://www.w3.org/2000/svg"');
        document.documentElement.classList.add('sat-form-field-error-icon');
        document.documentElement.style.setProperty(
          '--sat-form-field-error-mask-image',
          `url("data:image/svg+xml,${encodeURIComponent(standaloneSvg)}")`,
        );
      }
    }),
  ]);
}
